package com.campus.lostfound.controller;
import com.campus.lostfound.domain.*; import com.campus.lostfound.repository.*; import com.campus.lostfound.service.*; import jakarta.servlet.http.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.security.core.*; import org.springframework.security.core.context.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api") public class ApiController {
 private final AuditLogRepository auditLogs;private final UserRepository users;private final HandoverRepository handovers;private final ItemReportRepository reports;private final LostReportRepository lost;private final FoundReportRepository found;private final ClaimRepository claims;private final MatchRepository matches;private final NotificationRepository notifications;private final PasswordEncoder encoder;private final MatchingService matching;private final NotificationService notify;
 public ApiController(AuditLogRepository al,UserRepository u,HandoverRepository h,ItemReportRepository r,LostReportRepository l,FoundReportRepository f,ClaimRepository c,MatchRepository m,NotificationRepository n,PasswordEncoder e,MatchingService ms,NotificationService ns){auditLogs=al;users=u;handovers=h;reports=r;lost=l;found=f;claims=c;matches=m;notifications=n;encoder=e;matching=ms;notify=ns;}
 record Register(@NotBlank String fullName,@Email @NotBlank String email,@Size(min=8) String password,@NotBlank String campusId,String department,String userType){}
 record Login(@Email String email,@NotBlank String password){}
 record ReportInput(@NotBlank String title,@NotBlank String description,@NotBlank String category,@NotBlank String location,@NotNull LocalDate date,String imagePath,String time,String storageLocation,String privateDetails){}
 record ClaimInput(@NotNull UUID foundReportId,@NotBlank String reason,@NotBlank String privateEvidence){}
 record ReportUpdate(String title,String description,String category,String location,LocalDate date,String imagePath){}
 record ReviewInput(boolean approve,String comment){}
 record HandoverInput(@NotNull UUID claimId,@NotBlank String meetingLocation,@NotNull Instant scheduledAt){}
 private User current(Authentication auth){if(auth==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return users.findByEmail(auth.getName()).orElseThrow();}
 @GetMapping("/csrf") public Object csrf(org.springframework.security.web.csrf.CsrfToken token){return Map.of("token",token.getToken());}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@Valid @RequestBody Register in){if(users.findByEmail(in.email.toLowerCase()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");Role role=Role.STUDENT;User u=users.save(new User(in.fullName,in.email,encoder.encode(in.password),in.campusId,in.department,role));return ResponseEntity.status(201).body(userDto(u));}
 @PostMapping("/auth/login") public Object login(@Valid @RequestBody Login in,HttpServletRequest req){User u=users.findByEmail(in.email.toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(in.password,u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");Authentication a=new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+u.getRole())));SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(a);SecurityContextHolder.setContext(context);req.getSession(true).setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,context);return userDto(u);}
 @GetMapping("/auth/me") public Object me(Authentication a){return userDto(current(a));}
 @GetMapping("/public/stats") public Object stats(){return Map.of("reports",reports.count(),"lost",reports.countByType(ReportType.LOST),"found",reports.countByType(ReportType.FOUND),"active",reports.countByStatus(ReportStatus.ACTIVE),"users",users.count(),"returned",reports.countByStatus(ReportStatus.RETURNED));}
 @GetMapping("/public/reports") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object publicReports(@RequestParam(required=false) ReportType type,@RequestParam(required=false) String q,@RequestParam(required=false) String category){String query=Objects.toString(q,"").trim().toLowerCase();String selectedCategory=Objects.toString(category,"").trim();return reports.findAll().stream().filter(r->r.getStatus()==ReportStatus.ACTIVE).filter(r->type==null||r.getType()==type).filter(r->selectedCategory.isEmpty()||r.getCategory().equalsIgnoreCase(selectedCategory)).filter(r->query.isEmpty()||(r.getTitle()+" "+r.getDescription()+" "+r.getLocation()).toLowerCase().contains(query)).sorted(Comparator.comparing(ItemReport::getCreatedAt).reversed()).map(this::reportDto).toList();}
 @GetMapping("/reports/{id}") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object report(@PathVariable UUID id){return reportDto(reports.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}
 @PostMapping("/uploads") public Object upload(@RequestParam("file") org.springframework.web.multipart.MultipartFile file){if(file.isEmpty()||file.getSize()>5*1024*1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an image up to 5 MB");String mime=file.getContentType();String ext=switch(Objects.toString(mime,"")){case "image/jpeg"->"jpg";case "image/png"->"png";case "image/webp"->"webp";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only JPG, PNG, or WebP images are supported");};try{java.nio.file.Path root=java.nio.file.Path.of(System.getProperty("campus.upload.dir","uploads")).toAbsolutePath().normalize();java.nio.file.Files.createDirectories(root);String filename=UUID.randomUUID()+"."+ext;java.nio.file.Files.copy(file.getInputStream(),root.resolve(filename));return Map.of("url","/media/"+filename);}catch(java.io.IOException ex){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Image could not be stored");}}
 @PutMapping("/reports/{id}") @org.springframework.transaction.annotation.Transactional public Object updateReport(@PathVariable UUID id,@RequestBody ReportUpdate in,Authentication a){ItemReport r=reports.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));User actor=current(a);if(!r.getReporter().getId().equals(actor.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the report owner can edit it");if(r.getStatus()!=ReportStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active reports can be edited");r.updateDetails(in.title,in.description,in.category,in.location,in.date,in.imagePath);return reportDto(r);}
 @PutMapping("/reports/{id}/deactivate") @org.springframework.transaction.annotation.Transactional public Object deactivate(@PathVariable UUID id,Authentication a){ItemReport r=reports.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));User actor=current(a);if(!r.getReporter().getId().equals(actor.getId())&&actor.getRole()==Role.STUDENT)throw new ResponseStatusException(HttpStatus.FORBIDDEN);r.close();auditLogs.save(new AuditLog(actor,"REPORT_DEACTIVATED",r.getId().toString()));return reportDto(r);}
 @GetMapping("/admin/reports") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object adminReports(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){if(size<1||size>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);return reports.findAll(org.springframework.data.domain.PageRequest.of(page,size,org.springframework.data.domain.Sort.by("createdAt").descending())).map(this::reportDto);}
 @PutMapping("/admin/users/{id}/role") public Object updateRole(@PathVariable UUID id,@RequestBody Map<String,String> body,Authentication a){User actor=current(a);if(actor.getRole()!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only administrators can change roles");User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Role role;try{role=Role.valueOf(body.get("role"));}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");}u.setRole(role);auditLogs.save(new AuditLog(actor,"USER_ROLE_CHANGED",u.getId()+" -> "+role));return userDto(u);}
 @GetMapping("/admin/users") public Object adminUsers(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return users.findAll(org.springframework.data.domain.PageRequest.of(page,Math.min(Math.max(size,1),100))).map(this::userDto);}
 @PutMapping("/users/me") public Object updateProfile(@RequestBody Map<String,String> body,Authentication a){User u=current(a);u.updateProfile(body.get("fullName"),body.get("department"));return userDto(u);}
 @PutMapping("/users/me/password") public Object changePassword(@RequestBody Map<String,String> body,Authentication a){User u=current(a);if(!encoder.matches(Objects.toString(body.get("currentPassword"),""),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect");if(Objects.toString(body.get("newPassword"),"").length()<8)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"New password must be at least 8 characters");u.setPasswordHash(encoder.encode(body.get("newPassword")));return Map.of("updated",true);}
 @PutMapping("/notifications/{id}/read") public Object markRead(@PathVariable UUID id,Authentication a){AppNotification n=notifications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!n.getRecipient().getId().equals(current(a).getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);n.markRead();return Map.of("updated",true);}
 @PutMapping("/notifications/read-all") public Object readAll(Authentication a){notifications.findByRecipientIdOrderByCreatedAtDesc(current(a).getId()).forEach(AppNotification::markRead);return Map.of("updated",true);}
 @PostMapping("/reports/lost") public Object createLost(@Valid @RequestBody ReportInput in,Authentication a){User u=current(a);LostReport r=lost.save(new LostReport(in.title,in.description,in.category,in.location,in.date,in.imagePath,u,in.time));matching.match(r);return reportDto(r);}
 @PostMapping("/reports/found") public Object createFound(@Valid @RequestBody ReportInput in,Authentication a){User u=current(a);FoundReport r=found.save(new FoundReport(in.title,in.description,in.category,in.location,in.date,in.imagePath,u,in.time,in.storageLocation,in.privateDetails));matching.match(r);return reportDto(r);}
 @GetMapping("/reports/mine") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object mine(Authentication a){return reports.findAll().stream().filter(r->r.getReporter().getId().equals(current(a).getId())).map(this::reportDto).toList();}
 @GetMapping("/matches") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object myMatches(Authentication a){User u=current(a);return matches.findAllByOrderByScoreDesc().stream().filter(m->m.getLost().getReporter().getId().equals(u.getId())||m.getFound().getReporter().getId().equals(u.getId())).map(m->Map.of("id",m.getId(),"score",m.getScore(),"lost",reportDto(m.getLost()),"found",reportDto(m.getFound()))).toList();}
 @PostMapping("/claims") public ResponseEntity<?> createClaim(@Valid @RequestBody ClaimInput in,Authentication a){User u=current(a);FoundReport f=found.findById(in.foundReportId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(f.getReporter().getId().equals(u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot claim your own found report");if(f.getStatus()!=ReportStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"This item is no longer available");if(claims.existsByFoundReportIdAndClaimantIdAndStatusIn(f.getId(),u.getId(),List.of(ClaimStatus.PENDING,ClaimStatus.UNDER_REVIEW,ClaimStatus.APPROVED)))throw new ResponseStatusException(HttpStatus.CONFLICT,"You already have an active claim");return ResponseEntity.status(201).body(claimDto(claims.save(new Claim(f,u,in.reason,in.privateEvidence)),false));}
 @GetMapping("/claims/my") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object myClaims(Authentication a){return claims.findByClaimantIdOrderByCreatedAtDesc(current(a).getId()).stream().map(c->claimDto(c,false)).toList();}
 @GetMapping("/admin/claims") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object allClaims(){return claims.findAllByOrderByCreatedAtDesc().stream().map(c->claimDto(c,true)).toList();}
 @PostMapping("/admin/claims/{id}/review") @org.springframework.transaction.annotation.Transactional public Object review(@PathVariable UUID id,@RequestBody ReviewInput in,Authentication a){User reviewer=current(a);Claim c=claims.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(c.getStatus()!=ClaimStatus.PENDING&&c.getStatus()!=ClaimStatus.UNDER_REVIEW)throw new ResponseStatusException(HttpStatus.CONFLICT,"Claim has already been reviewed");if(in.approve&&c.getFoundReport().getStatus()!=ReportStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"This item is no longer available for another claim");c.review(reviewer,in.approve,in.comment);auditLogs.save(new AuditLog(reviewer,in.approve?"CLAIM_APPROVED":"CLAIM_REJECTED",c.getId().toString()));if(in.approve)c.getFoundReport().markClaimed();claims.save(c);notify.notify(c.getClaimant(),in.approve?"Your ownership claim was approved. Please coordinate a handover with campus staff.":"Your ownership claim was not approved.");return claimDto(c,true);}
 @PostMapping("/admin/handovers") @org.springframework.transaction.annotation.Transactional public ResponseEntity<?> createHandover(@Valid @RequestBody HandoverInput in,Authentication a){User staff=current(a);Claim claim=claims.findById(in.claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(claim.getStatus()!=ClaimStatus.APPROVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only approved claims can be handed over");if(in.scheduledAt.isBefore(Instant.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Handover time must be in the future");Handover handover=handovers.save(new Handover(claim,staff,in.meetingLocation,in.scheduledAt));auditLogs.save(new AuditLog(staff,"HANDOVER_SCHEDULED",handover.getId().toString()));notify.notify(claim.getClaimant(),"A handover has been scheduled at "+in.meetingLocation+".");return ResponseEntity.status(201).body(handoverDto(handover));}
 @GetMapping("/admin/handovers") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object allHandovers(){return handovers.findAllByOrderByScheduledAtDesc().stream().map(this::handoverDto).toList();}
 @GetMapping("/handovers/my") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object myHandovers(Authentication a){UUID userId=current(a).getId();return handovers.findAllByOrderByScheduledAtDesc().stream().filter(h->h.getClaim().getClaimant().getId().equals(userId)).map(this::handoverDto).toList();}
 @PostMapping("/handovers/{id}/confirm") @org.springframework.transaction.annotation.Transactional public Object confirmHandover(@PathVariable UUID id,Authentication a){Handover h=handovers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!h.getClaim().getClaimant().getId().equals(current(a).getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);try{h.confirmOwner();}catch(IllegalStateException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,ex.getMessage());}return handoverDto(h);}
 @PostMapping("/admin/handovers/{id}/complete") @org.springframework.transaction.annotation.Transactional public Object completeHandover(@PathVariable UUID id){Handover h=handovers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));try{h.complete();}catch(IllegalStateException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,ex.getMessage());}h.getClaim().getFoundReport().markReturned();auditLogs.save(new AuditLog(h.getCoordinator(),"HANDOVER_COMPLETED",h.getId().toString()));notify.notify(h.getClaim().getClaimant(),"Your item handover is complete. We hope it serves you well!");return handoverDto(h);}
 private Object handoverDto(Handover h){return Map.of("id",h.getId(),"claimId",h.getClaim().getId(),"item",h.getClaim().getFoundReport().getTitle(),"claimant",h.getClaim().getClaimant().getFullName(),"coordinator",h.getCoordinator().getFullName(),"meetingLocation",h.getMeetingLocation(),"scheduledAt",h.getScheduledAt(),"status",h.getStatus());}
 @GetMapping("/notifications") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object notificationList(Authentication a){return notifications.findByRecipientIdOrderByCreatedAtDesc(current(a).getId()).stream().map(n->Map.of("id",n.getId(),"message",n.getMessage(),"createdAt",n.getCreatedAt(),"read",n.isRead())).toList();}
 @GetMapping("/dashboard") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object dashboard(Authentication a){User u=current(a);List<ItemReport> own=reports.findAll().stream().filter(r->r.getReporter().getId().equals(u.getId())).toList();return Map.of("user",userDto(u),"lostReports",own.stream().filter(r->r.getType()==ReportType.LOST).count(),"foundReports",own.stream().filter(r->r.getType()==ReportType.FOUND).count(),"activeClaims",claims.findByClaimantIdOrderByCreatedAtDesc(u.getId()).stream().filter(c->c.getStatus()==ClaimStatus.PENDING||c.getStatus()==ClaimStatus.UNDER_REVIEW).count(),"matches",myMatches(a),"recentReports",own.stream().sorted(Comparator.comparing(ItemReport::getCreatedAt).reversed()).limit(5).map(this::reportDto).toList());}
 @GetMapping("/admin/audit") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object auditHistory(){return auditLogs.findTop200ByOrderByCreatedAtDesc().stream().map(e->Map.of("id",e.getId(),"actor",e.getActor().getFullName(),"action",e.getAction(),"target",e.getTarget(),"createdAt",e.getCreatedAt())).toList();}
 @GetMapping("/admin/dashboard") @org.springframework.transaction.annotation.Transactional(readOnly=true) public Object adminDashboard(){return Map.of("users",users.count(),"lost",reports.countByType(ReportType.LOST),"found",reports.countByType(ReportType.FOUND),"pendingClaims",claims.countByStatus(ClaimStatus.PENDING),"returned",reports.countByStatus(ReportStatus.RETURNED),"activeReports",reports.countByStatus(ReportStatus.ACTIVE));}
 private Object userDto(User u){return Map.of("id",u.getId(),"fullName",u.getFullName(),"email",u.getEmail(),"role",u.getRole());}
 private Object reportDto(ItemReport r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getId());m.put("title",r.getTitle());m.put("description",r.getDescription());m.put("category",r.getCategory());m.put("location",r.getLocation());m.put("date",r.getIncidentDate());m.put("type",r.getType());m.put("status",r.getStatus());m.put("imagePath",Objects.toString(r.getImagePath(),""));m.put("reporter",r.getReporter().getFullName());m.put("createdAt",r.getCreatedAt());return m;}
 private Object claimDto(Claim c,boolean privileged){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("foundReport",reportDto(c.getFoundReport()));m.put("status",c.getStatus());m.put("reason",c.getReason());m.put("createdAt",c.getCreatedAt());if(privileged){m.put("privateEvidence",c.getPrivateEvidence());m.put("claimant",userDto(c.getClaimant()));}return m;}
}
